import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './HealthAssessment.css';

const HealthAssessment = () => {
  const navigate = useNavigate();
  const API_BASE_URL = 
    process.env.NODE_ENV === 'production'
      ? 'https://airaware-app-gcw7.onrender.com'
      : 'http://localhost:8000';

  // Professional Health Assessment Initial State
  const [assessmentData, setAssessmentData] = useState({
    personalInfo: {
      fullName: '',
      age: '',
      gender: '',
      contactNumber: ''
    },
    medicalHistory: {
      chronicConditions: [],
      currentMedications: '',
      allergies: []
    },
    respiratoryProfile: {
      smokingStatus: '',
      occupationalExposure: '',
      environmentalFactors: []
    },
    symptomsAssessment: {
      respiratorySymptons: [],
      frequencyOfSymptoms: ''
    }
  });

  // Comprehensive Validation State
  const [validationErrors, setValidationErrors] = useState({});
  const [submissionStatus, setSubmissionStatus] = useState({
    isSubmitting: false,
    errorMessage: '',
    successMessage: ''
  });

  // Predefined Professional Options
  const PROFESSIONAL_OPTIONS = {
    genderCategories: [
      'Male', 'Female', 'Non-Binary', 'Prefer Not to Say'
    ],
    chronicConditions: [
      'Asthma', 'COPD', 'Bronchitis', 
      'Pulmonary Fibrosis', 'None'
    ],
    smokingStatuses: [
      'Never Smoked', 'Current Smoker', 
      'Ex-Smoker', 'Occasional Smoker'
    ],
    respiratorySymptons: [
      'Persistent Cough', 'Shortness of Breath', 
      'Chest Tightness', 'Wheezing', 'None'
    ]
  };

  // Comprehensive Input Change Handler
  const handleInputChange = (e, section, field) => {
    const { value, type, checked } = e.target;

    setAssessmentData(prevData => {
      const updatedSection = type === 'checkbox' 
        ? {
            ...prevData[section],
            [field]: checked 
              ? [...(prevData[section][field] || []), value]
              : (prevData[section][field] || []).filter(item => item !== value)
          }
        : {
            ...prevData[section],
            [field]: value
          };

      return {
        ...prevData,
        [section]: updatedSection
      };
    });

    // Clear specific field validation error
    setValidationErrors(prev => ({
      ...prev,
      [`${section}.${field}`]: ''
    }));
  };

  // Professional Validation Logic
  const validateHealthAssessment = () => {
    const errors = {};

    // Personal Info Validation
    if (!assessmentData.personalInfo.fullName.trim()) {
      errors['personalInfo.fullName'] = 'Full Name is required';
    }
    if (!assessmentData.personalInfo.age) {
      errors['personalInfo.age'] = 'Age is required';
    }
    if (!assessmentData.personalInfo.gender) {
      errors['personalInfo.gender'] = 'Gender selection is required';
    }

    // Medical History Basic Validation
    if (assessmentData.medicalHistory.chronicConditions.length === 0) {
      errors['medicalHistory.chronicConditions'] = 'Please select at least one condition';
    }

    setValidationErrors(errors);
    return Object.keys(errors).length === 0;
  };

  // Submission Handler
  const handleSubmit = async (event) => {
    event.preventDefault();
    
    // Reset submission status
    setSubmissionStatus({
      isSubmitting: true,
      errorMessage: '',
      successMessage: ''
    });

    // Validate before submission
    if (!validateHealthAssessment()) {
      setSubmissionStatus(prev => ({
        ...prev, 
        isSubmitting: false,
        errorMessage: 'Please complete all required fields'
      }));
      return;
    }

    try {
      const user = JSON.parse(localStorage.getItem('user'));
      const csrfToken = document.cookie.split('; ')
        .find(row => row.startsWith('csrftoken='))
        ?.split('=')[1];

      const response = await fetch(`${API_BASE_URL}/api/health-assessment/`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-CSRFToken': csrfToken
        },
        credentials: 'include',
        body: JSON.stringify({
          userId: user.user_id,
          ...assessmentData
        })
      });

      const responseData = await response.json();

      if (response.ok) {
        // Update user's health assessment status
        localStorage.setItem('user', JSON.stringify({
          ...user,
          hasHealthAssessment: true
        }));

        setSubmissionStatus({
          isSubmitting: false,
          successMessage: 'Health Assessment Submitted Successfully',
          errorMessage: ''
        });

        // Navigate to dashboard after successful submission
        navigate('/dashboard');
      } else {
        throw new Error(responseData.message || 'Submission Failed');
      }

    } catch (error) {
      setSubmissionStatus({
        isSubmitting: false,
        errorMessage: error.message || 'Network Error',
        successMessage: ''
      });
    }
  };

  return (
    <div className="professional-health-assessment">
      <h1>Comprehensive Health Assessment</h1>
      
      {/* Submission Status Messages */}
      {submissionStatus.errorMessage && (
        <div className="error-message">
          {submissionStatus.errorMessage}
        </div>
      )}

      <form onSubmit={handleSubmit}>
        {/* Personal Information Section */}
        <section>
          <h2>Personal Information</h2>
          {/* Input fields with validation */}
          {/* Similar structure for other sections */}
        </section>

        <button 
          type="submit" 
          disabled={submissionStatus.isSubmitting}
        >
          {submissionStatus.isSubmitting 
            ? 'Submitting...' 
            : 'Complete Health Assessment'}
        </button>
      </form>
    </div>
  );
};

export default HealthAssessment;
